-- GENERATED by gen_topic_view.py from ctgov-discovery/scripts/04_mine_terms.py CATEGORIES (+ FIXES). Do not edit.
-- One-Trial test, step 4: Criterion topic view over our Postgres `criterion` table (registered as datasource
-- `trialmatch` in db/zetaris_register.sql). One Criterion can have several topics; topics only route.

-- Container (once per name; skip if it exists).
-- OUTCOME: NOT RUN
CREATE SCHEMASTORE CONTAINER trialmatch_views;

-- OUTCOME: NOT RUN
CREATE SCHEMASTORE VIEW criterion_topic WITH CONTAINER trialmatch_views AS
SELECT c.id AS criterion_id, c.nct_id, c.eligibility_hash, c.kind, c.ordinal, topic
FROM trialmatch.criterion c
LATERAL VIEW explode(array(
    CASE WHEN c.text RLIKE '(?i)\\b(aged?|years? (?:of age|old)|≥\\s*\\d+\\s*years|\\bmale|female|women|men|sex|gender)\\b' THEN 'age_sex' END,
    CASE WHEN c.text RLIKE '(?i)\\b(histolog\\w*|cytolog\\w*|patholog\\w*|confirmed (?:diagnosis|by)|diagnos\\w+ (?:of|with))\\b' THEN 'diagnosis_histology' END,
    CASE WHEN c.text RLIKE '(?i)\\b(stage\\s*(?:[IV]+|[0-4])[ABC]?|staging|grade\\s*[1-4IV]|risk (?:group|stratum|category)|high[- ]risk|low[- ]risk|metasta\\w+|advanced|locally advanced|unresectable)\\b' THEN 'stage_grade_risk' END,
    CASE WHEN c.text RLIKE '(?i)\\b(relaps\\w*|refractory|recurr\\w*|progress\\w* (?:on|after|following)|resistant)\\b' THEN 'relapsed_refractory' END,
    CASE WHEN c.text RLIKE '(?i)\\b(EGFR|ALK|ROS-?1|KRAS|BRAF|MET(?:\\s+exon)?|RET|NTRK|HER-?2|ERBB2|PD-?L1|MSI(?:-H)?|dMMR|MMR|TMB|MYCN|H3\\s?K27M|fusion|rearrange\\w+|mutation\\w*|amplification|germline|BCR-?ABL|Philadelphia|FLT3|IDH[12]|NPM1|KMT2A|MLL|ETV6|biomarker|gene\\w*|molecular|variant)\\b' THEN 'biomarker_genetic' END,
    CASE WHEN c.text RLIKE '(?i)\\b(ECOG|Karnofsky|Lansky|performance status|WHO PS|KPS)\\b' THEN 'performance_status' END,
    CASE WHEN c.text RLIKE '(?i)\\b(ANC|neutrophil\\w*|platelet\\w*|ha?emoglobin|Hgb|Hb|bilirubin|ALT|AST|SGOT|SGPT|transaminase\\w*|creatinine|(?-i:eGFR)|GFR|CrCl|creatinine clearance|INR|PT|aPTT|LVEF|ejection fraction|QTc\\w*|albumin|ULN|organ function|bone marrow function|hepatic function|renal function|lab(?:oratory)? values?)\\b' THEN 'labs_organ_function' END,
    CASE WHEN c.text RLIKE '(?i)\\b(RECIST|INRC|RANO|iRECIST|measurable|evaluable disease|target lesion\\w*|Lugano|MRD|minimal residual)\\b' THEN 'measurable_disease' END,
    CASE WHEN c.text RLIKE '(?i)\\b(prior|previous\\w*|previously|received|pretreated|treatment[- ]naive|naive|line\\w* of (?:therapy|treatment)|chemotherap\\w+|radiotherap\\w+|radiation|surgery|resection|transplant\\w*|HSCT|washout|within \\d+ (?:days|weeks|months) (?:of|prior|before)|inhibitor|immunotherap\\w+|checkpoint|anti-PD-?1|anti-PD-?L1|tyrosine kinase|TKI|monoclonal|investigational (?:agent|drug|product))\\b' THEN 'prior_treatment' END,
    CASE WHEN c.text RLIKE '(?i)\\b(CNS|central nervous system|brain metasta\\w+|leptomeningeal|intracranial|carcinomatous meningitis|spinal cord compression)\\b' THEN 'cns_brain_mets' END,
    CASE WHEN c.text RLIKE '(?i)\\b(HIV|hepatitis|HBV|HCV|HBsAg|tuberculosis|TB|autoimmune|interstitial lung|pneumonitis|cardiac|heart failure|myocardial|arrhythmi\\w+|angina|stroke|infection|second(?:ary)? (?:primary )?malignanc\\w+|other malignanc\\w+|prior malignanc\\w+|another (?:primary )?(?:cancer|malignancy)|diabetes|hypertension|COVID|organ transplant)\\b' THEN 'comorbidity_infection' END,
    CASE WHEN c.text RLIKE '(?i)\\b(CYP3A4?|CYP\\d\\w*|P-?gp|strong (?:inhibitor|inducer)\\w*|steroid\\w*|corticosteroid\\w*|prednisone|dexamethasone|anticoagula\\w+|warfarin|immunosuppress\\w+|concomitant|live (?:attenuated )?vaccin\\w+|vaccin\\w+)\\b' THEN 'concomitant_meds' END,
    CASE WHEN c.text RLIKE '(?i)\\b(pregnan\\w+|breast[- ]?feeding|lactat\\w+|nursing|contracepti\\w+|childbearing|WOCBP|sperm|abstinen\\w+|menopaus\\w+)\\b' THEN 'pregnancy_contraception' END,
    CASE WHEN c.text RLIKE '(?i)\\b(consent|assent|life expectancy|comply|complian\\w+|willing|able to (?:understand|swallow|attend)|travel|language|follow-?up visits|geographic\\w*)\\b' THEN 'consent_logistics' END
)) AS topic
WHERE topic IS NOT NULL;

-- Expect for NCT07680790 (same as 07_one_trial.py, minus labs_organ_function on ordinal 2):
-- 1 diagnosis_histology, stage_grade_risk, relapsed_refractory, prior_treatment
-- 2 biomarker_genetic, prior_treatment
-- 3 measurable_disease
-- 4 performance_status
-- 5 stage_grade_risk, cns_brain_mets
-- 6 stage_grade_risk, comorbidity_infection, concomitant_meds
-- 7 comorbidity_infection
-- 8 (none)
-- OUTCOME: NOT RUN
SELECT ordinal, concat_ws(', ', collect_list(topic)) AS topics
FROM trialmatch_views.criterion_topic
WHERE nct_id = 'NCT07680790'
GROUP BY ordinal ORDER BY ordinal;

